'use strict'
/**
 * cdpc 健壮性压力测试台
 *
 * 运行：node test/test-robust.js
 *      ROBUST_PORT=34700 node test/test-robust.js
 *
 * 这一组用例针对的是「跑久了才会暴露」的问题：进程堆积、崩溃循环、
 * 高频操作下的竞态、并发连接打满。都是当年反复调整进程管理设计时踩过的坑。
 *
 *   R1 worker 起来就崩 —— launcher 必须熔断而不是无限 fork
 *   R2 高频 restart churn —— 不能堆积历史进程，重复调用要去重
 *   R3 sock 并发连接打满 —— 超限要拒绝，服务本身不能被压死
 *   R4 单连接管线化 —— 请求必须按 id 正确配对
 *   R5 同时管理 25 个服务 —— 批量移除零残留
 *   R6 调整 workers 数量 —— 起够数量、移除干净
 */
const fs = require('node:fs')
const net = require('node:net')
const os = require('node:os')
const {spawnSync} = require('node:child_process')
const CDPC = require('../index')

const W = `${os.tmpdir()}/cdpc-robust-${process.pid}`
const SOCK = `${W}/d.sock`
// 同 test-cluster.js：专属变量优先，避免 npm test 里三个脚本抢同一个端口
const P0 = parseInt(process.env.ROBUST_PORT
      || (process.env.TEST_PORT ? String(parseInt(process.env.TEST_PORT, 10) + 2) : '34700'), 10)

let pass = 0, fail = 0
const failed = []
const ok = (c, t, e = '') => {
  if (c) { pass++; console.log(`  \x1b[32mPASS\x1b[0m ${t}`) }
  else { fail++; failed.push(t); console.log(`  \x1b[31mFAIL\x1b[0m ${t}${e ? '  <' + e + '>' : ''}`) }
}
const sleep = ms => new Promise(r => setTimeout(r, ms))
const alive = p => { try { process.kill(p, 0); return true } catch (e) { return false } }
const sh = c => (spawnSync('bash', ['-c', c + ' || true'], {encoding: 'utf8', timeout: 10000}).stdout || '').trim()
async function until(f, t = 20000, s = 300) {
  let n = 0
  while (n < t) { try { if (await f()) return true } catch (e) {} await sleep(s); n += s }
  return false
}

process.chdir(__dirname)

fs.mkdirSync(`${W}/state`, {recursive: true, mode: 0o755})

// 起来就崩的 worker
fs.writeFileSync(`${W}/crash.js`, "process.exit(7)\n")
// 正常 http worker
fs.writeFileSync(`${W}/web.js`, [
  "const http=require('http')",
  "process.on('SIGTERM',()=>setTimeout(()=>process.exit(0),100))",
  `http.createServer((q,s)=>s.end(String(process.pid))).listen(${P0},'0.0.0.0')`
].join('\n'))
fs.writeFileSync(`${W}/idle.js`, "setInterval(()=>{},1000)\n")

const cm = new CDPC({stateDir: `${W}/state`, sockFile: SOCK, errorHandle: () => {}})
const pgrepN = pat => parseInt(sh(`pgrep -c -f '${pat}'`) || '0', 10)
const workers = () => {
  let o = sh(`pgrep -af '${W}/we[b].js'`)
  if (!o) return []
  return o.split('\n').filter(l => l && l.indexOf('launcher.js') < 0)
        .map(l => parseInt(l.split(' ')[0], 10)).filter(p => p > 0)
}

const req = (op, extra = {}, id = 1) => new Promise((rv, rj) => {
  let c = net.connect(SOCK), buf = ''
  let tm = setTimeout(() => { c.destroy(); rj(new Error('timeout')) }, 6000)
  c.on('connect', () => c.write(JSON.stringify({v: 1, id, op, ...extra}) + '\n'))
  c.on('data', d => {
    buf += d
    let i = buf.indexOf('\n')
    if (i < 0) return
    clearTimeout(tm); c.end()
    try { rv(JSON.parse(buf.slice(0, i))) } catch (e) { rj(e) }
  })
  c.on('error', e => { clearTimeout(tm); rj(e) })
})

;(async () => {
  cm.monitorStart()
  await until(async () => { try { return fs.lstatSync(SOCK).isSocket() } catch (e) { return false } }, 8000, 200)

  // ---------- R1 worker 崩溃循环的熔断 ----------
  console.log('\n[R1] worker 起来就崩：launcher 必须熔断，而不是无限 fork')
  cm.add({name: 'crash', file: `${W}/crash.js`, cluster: true, workers: 2,
          restart: 'none', options: {stdio: ['ignore', 'ignore', 'ignore']}})

  let died = await until(async () => cm.stateName[cm.find('crash').state] === 'EXIT', 30000, 500)
  let leaked = pgrepN(`${W}/cras[h].js`)

  ok(died, 'launcher 熔断后退出，cdpc 侧转为 EXIT，不会无限刷进程')
  ok(leaked === 0, '崩溃循环没有留下任何残留进程', `残留 ${leaked}`)
  cm.remove('crash')

  // ---------- R2 高频 churn ----------
  console.log('\n[R2] 高频 start/stop/restart churn（cluster 服务）')
  cm.add({name: 'web', file: `${W}/web.js`, cluster: true, workers: 2,
          restart: 'always', restartDelay: 300, options: {stdio: ['ignore', 'ignore', 'ignore']}})

  let up = await until(async () => workers().length === 2, 25000, 500)
  ok(up, `前置：2 个 worker（实际 ${workers().length}）`)

  let seen = new Set()
  let swallowed = 0
  let rounds = 0

  for (let i = 0; i < 10; i++) {
    let lp = cm.find('web').child.pid
    // 连打 3 次 restart：只有第一次应该生效，其余被 restarting 标志吞掉
    cm.restart('web'); cm.restart('web'); cm.restart('web')
    let changed = await until(async () => {
      let c = cm.find('web')
      return c && c.child && c.child.pid !== lp && workers().length === 2
    }, 25000, 200)
    if (changed) rounds++
    workers().forEach(p => seen.add(p))
    let n = workers().length
    if (n > 2) swallowed++
  }

  let settled = await until(async () => workers().length === 2, 30000, 500)
  ok(settled, `10 轮 restart 后稳定在 2 个 worker（实际 ${workers().length}）`)
  ok(rounds === 10, `每一轮 restart 都真实完成并换了 launcher（${rounds}/10）`)
  ok(swallowed === 0,
     '连打 3 次 restart 不会叠加出多余 worker（restarting 标志做了去重）')
  ok(seen.size >= 10, `确实反复换了进程（共观察到 ${seen.size} 个 worker pid）`)
  ok(Array.from(seen).filter(alive).length <= 2,
     '历史 worker 没有堆积，只剩当前这一组', `存活 ${Array.from(seen).filter(alive).length}`)
  ok(!!sh(`timeout 2 curl -s http://127.0.0.1:${P0}/`), 'churn 之后端口正常服务')

  // ---------- R3 sock 并发连接 ----------
  console.log('\n[R3] sock 并发连接（上限 32，压 80 个）')
  let results = await Promise.allSettled(
    Array.from({length: 80}, (_, i) => req('ping', {}, i + 1)))
  let okc = results.filter(r => r.status === 'fulfilled' && r.value.ok).length

  ok(okc > 0, `并发 80 个连接里 ${okc} 个成功`)
  let stillOk = await req('ping')
  ok(stillOk.ok === true, '超出上限被拒绝后 sock 服务依然健康（没有被压死）')

  // ---------- R4 管线化 ----------
  console.log('\n[R4] 单连接管线化 200 个请求')
  let pipeOk = await new Promise(rv => {
    let c = net.connect(SOCK), buf = '', got = new Set()
    let tm = setTimeout(() => { c.destroy(); rv(got.size) }, 15000)
    c.on('connect', () => {
      let s = ''
      for (let i = 1; i <= 200; i++) s += JSON.stringify({v: 1, id: i, op: 'ping'}) + '\n'
      c.write(s)
    })
    c.on('data', d => {
      buf += d
      let i
      while ((i = buf.indexOf('\n')) >= 0) {
        let line = buf.slice(0, i); buf = buf.slice(i + 1)
        try { got.add(JSON.parse(line).id) } catch (e) {}
      }
      if (got.size >= 200) { clearTimeout(tm); c.end(); rv(got.size) }
    })
    c.on('error', () => { clearTimeout(tm); rv(got.size) })
  })
  ok(pipeOk === 200, `200 个管线请求全部按 id 配对返回（实际 ${pipeOk}）`)

  // ---------- R5 多服务并发 ----------
  console.log('\n[R5] 同时管理 25 个服务')
  for (let i = 0; i < 25; i++) {
    cm.add({name: `s${i}`, file: `${W}/idle.js`, restart: 'always',
            options: {stdio: ['ignore', 'ignore', 'ignore']}})
  }
  let allUp = await until(async () => {
    let n = 0
    for (let i = 0; i < 25; i++) {
      let c = cm.find(`s${i}`)
      if (c && cm.stateName[c.state] === 'RUNNING') n++
    }
    return n === 25
  }, 40000, 500)
  ok(allUp, '25 个服务全部 RUNNING')

  let t0 = Date.now()
  let stt = await req('status')
  ok(stt.ok && stt.data.childs.length >= 26,
     `status 一次返回全部 ${stt.data ? stt.data.childs.length : 0} 个服务（${Date.now() - t0}ms）`)

  let idlePids = []
  for (let i = 0; i < 25; i++) {
    let c = cm.find(`s${i}`)
    if (c && c.child) idlePids.push(c.child.pid)
    cm.remove(`s${i}`)
  }
  await sleep(2500)
  ok(idlePids.filter(alive).length === 0, '25 个服务批量移除后零残留',
     `残留 ${idlePids.filter(alive).length}`)

  // ---------- R6 改 workers 数量 ----------
  console.log('\n[R6] 在线调整 workers 数量')
  cm.remove('web')
  await sleep(2000)
  cm.add({name: 'web', file: `${W}/web.js`, cluster: true, workers: 4,
          restart: 'always', options: {stdio: ['ignore', 'ignore', 'ignore']}})
  let four = await until(async () => workers().length === 4, 30000, 500)
  ok(four, `workers 改为 4 后确实起了 4 个（实际 ${workers().length}）`)

  let wp = workers()
  cm.remove('web')
  await sleep(3000)
  ok(wp.filter(alive).length === 0, '4 worker 组移除后零残留')

  // ---------- 收尾 ----------
  cm.sockStop()
  cm.monitorStop()
  cm.killAllChilds(process.pid, 'SIGKILL')
  await sleep(500)
  sh(`rm -rf ${W}`)

  console.log(`\n${'='.repeat(48)}\n通过 ${pass}，失败 ${fail}`)
  if (fail) { console.log('失败项：'); failed.forEach(f => console.log('  - ' + f)) }
  console.log('='.repeat(48))
  process.exit(fail ? 1 : 0)
})().catch(e => { console.error('探针异常', e); sh(`rm -rf ${W}`); process.exit(2) })
